#include "k1_asrc_24k.h"
#include <assert.h>
#include <string.h>
#include <stdio.h>
void legacy_reset(k1_asrc24_t *,uint32_t,uint32_t);
int legacy_set_rate(k1_asrc24_t *,uint32_t);
uint32_t legacy_required_for_pull180(const k1_asrc24_t *);
int legacy_push(k1_asrc24_t *,const int16_t *,uint32_t);
int legacy_pull180(k1_asrc24_t *,int16_t *);
int main(void) {
 uint32_t rates[]={36000,40000,41440,44000};
 for(unsigned r=0;r<4;++r) {
  k1_asrc24_t a,b;
  int16_t input[296],x[180],y[180];
  k1_asrc24_reset(&a,7,rates[r]);legacy_reset(&b,7,rates[r]);
  for(unsigned block=0;block<2000;++block) {
   for(unsigned i=0;i<296;++i)input[i]=(int16_t)((block*296u+i)*251u);
   assert(k1_asrc24_push(&a,input,296)==legacy_push(&b,input,296));
   assert(k1_asrc24_required_for_pull180(&a)==legacy_required_for_pull180(&b));
   for(;;) {
    memset(x,0x5a,sizeof x);memset(y,0x5a,sizeof y);
    int ra=k1_asrc24_pull180(&a,x),rb=legacy_pull180(&b,y);
    assert(ra==rb && memcmp(x,y,sizeof x)==0);
    assert(memcmp(&a,&b,sizeof a)==0);
    if(ra!=0)break;
   }
   if(block==1000)assert(k1_asrc24_set_rate(&a,41530)==legacy_set_rate(&b,41530));
  }
 }
 puts("LEGACY_ASRC_BYTE_PARITY=PASS 2368000 input samples across4rates");
 return 0;
}
